  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "BI 425809 25 mg tablet in fasted humans had absolute oral bioavailability 71.64% (90% CI 64.28-79.84) vs IV microtracer infusion, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Suvorexant 10 mg in fasted humans had mean absolute oral bioavailability 82%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pentazocine in healthy subjects had mean absolute oral bioavailability 18% vs IV, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most evidence molecules with comparable assay-transfer scores show direct absolute oral bioavailability values well above 20% in humans, including 71.6%, 82%, and 77%. One molecule, pentazocine, is directly below the threshold at 18%, but the preponderance of high-quality positive evidence supports a high F prediction.",
  "evidence_gaps": [
    "The only negative evidence is a single molecule with direct absolute F around 18% in healthy subjects, introducing some uncertainty despite many positive records.",
    "Some positive records are qualitative or not explicitly absolute, but the prediction relies on quantitative absolute measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

